begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
select ok(not (select rolcanlogin or rolinherit or rolbypassrls or rolsuper from pg_roles where rolname='wyp_playlist_fence'),'withdrawal fence role is restricted');
select is((select count(*)::integer from pg_tables where tableowner='wyp_playlist_fence'),0,'fence role owns no tables');
select ok(not has_table_privilege('wyp_playlist_fence','public.playlists','UPDATE'),'fence trigger cannot rewrite playlists');
select ok(not has_table_privilege('wyp_creator_rpc','private.playlist_versions','UPDATE'),'author role cannot rewrite immutable publications');
select ok(not has_table_privilege('wyp_creator_rpc','private.playlist_reviews','DELETE'),'review receipts cannot be deleted by author role');
select ok(not has_column_privilege('wyp_creator_rpc','public.playlists','creator_id','UPDATE'),'authoring role cannot transfer playlist ownership');
select ok(not has_column_privilege('wyp_creator_rpc','public.playlists','kind','UPDATE'),'authoring role cannot claim editorial status');
select ok(not has_column_privilege('wyp_creator_rpc','private.creator_profiles','user_id','UPDATE'),'profile ownership is immutable');
select ok(not has_table_privilege('anon','public.playlists','SELECT'),'browser cannot enumerate raw playlist headers');
select ok(not has_table_privilege('authenticated','private.creator_profiles','SELECT'),'public display label is projected through its RPC');
select ok(not has_table_privilege('authenticated','private.playlist_drafts','UPDATE'),'browser cannot mutate draft tables directly');
select ok(not has_function_privilege('anon','public.create_creator_playlist(uuid)','EXECUTE'),'guests cannot create playlists');
select ok(has_function_privilege('anon','public.get_library_playlist(uuid)','EXECUTE'),'guests can inspect metadata-only detail');
select ok(not has_function_privilege('authenticated','private.ensure_curated_starter_playlist()','EXECUTE'),'starter initializer is migration-only');
select ok(not has_function_privilege('authenticated','private.playlist_item_preview(uuid)','EXECUTE'),'private version lookup is not a browser RPC');
select ok(not has_function_privilege('wyp_media_validator','private.playlist_version_media_ready(uuid)','EXECUTE'),'validator gains no playlist discovery capability');
select ok(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private' and p.proname like '%playlist%' and (has_function_privilege('anon',p.oid,'EXECUTE') or has_function_privilege('authenticated',p.oid,'EXECUTE'))),'private playlist helpers have no client execute grant');
select ok(not exists(select 1 from pg_proc where proowner in ('wyp_rpc'::regrole,'wyp_creator_rpc'::regrole,'wyp_playlist_fence'::regrole) and (proconfig is null or not ('search_path=""'=any(proconfig)))),'all runtime helpers pin an empty search path');
insert into auth.users(id,email,email_confirmed_at) values
('71000000-0000-4000-8000-000000000001','playlist-owner@example.test',now()),
('71000000-0000-4000-8000-000000000002','playlist-other@example.test',now()),
('71000000-0000-4000-8000-000000000003','playlist-unverified@example.test',null);
create temporary table playlist_security_state(name text primary key,value jsonb);
grant select,insert,update on playlist_security_state to authenticated;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"71000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select throws_ok($$select public.get_creator_profile()$$,'P0001','CREATOR_REQUIRED','learner cannot access creator profile workflow');
select public.enable_creator();
select is(public.get_creator_profile(),'{"displayName":null,"revision":0}'::jsonb,'creator starts without manufactured public name');
insert into playlist_security_state values('draft',public.create_creator_playlist('71000000-0000-4000-8000-000000000010')->'playlist');
select is(public.create_creator_playlist('71000000-0000-4000-8000-000000000010')->>'replayed','true','create retries are idempotent');
select is(jsonb_array_length(public.list_creator_playlists()->'playlists'),1,'create retry leaves one draft');
select is(public.save_creator_profile('71000000-0000-4000-8000-000000000011',0,E'  TénZ\tCoach  ')->'profile'->>'displayName','TénZ Coach','public name normalizes whitespace preserving accents');
select is(public.save_creator_profile('71000000-0000-4000-8000-000000000011',0,'TénZ Coach')->>'replayed','true','normalized exact profile retry succeeds');
select throws_ok($$select public.save_creator_profile('71000000-0000-4000-8000-000000000011',0,'Another Coach')$$,'P0001','IDEMPOTENCY_CONFLICT','profile receipt binds payload');
select throws_ok($$select public.save_creator_profile('71000000-0000-4000-8000-000000000012',0,'Another Coach')$$,'P0001','CREATOR_PROFILE_CONFLICT','stale tab cannot replace public name');
select throws_ok(format('select public.get_creator_playlist_review_preview(%L,0)',value->>'id'),'P0001','DRAFT_NOT_READY','empty draft cannot be reviewed') from playlist_security_state where name='draft';
select throws_like('select * from private.playlist_drafts','%permission denied%','creator cannot read private raw rows');
select throws_ok($$select public.get_creator_playlist('7ecf3523-18cb-5cbe-a307-5b5cd43d1836')$$,'P0001','PLAYLIST_NOT_FOUND','curated starter is not a fake owned draft');
select set_config('request.jwt.claims','{"sub":"71000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select public.enable_creator();
select is(public.get_creator_profile(),'{"displayName":null,"revision":0}'::jsonb,'other creator does not receive private profile');
select is(jsonb_array_length(public.list_creator_playlists()->'playlists'),0,'other creator cannot list drafts');
select throws_ok(format('select public.get_creator_playlist(%L)',value->>'id'),'P0001','PLAYLIST_NOT_FOUND','other creator cannot read draft') from playlist_security_state where name='draft';
select set_config('request.jwt.claims','{"sub":"71000000-0000-4000-8000-000000000003","role":"authenticated"}',true);
select throws_ok('select public.get_creator_profile()','P0001','EMAIL_NOT_VERIFIED','unverified identity cannot use creator profile');
reset role;
select * from finish();
rollback;
